#!/usr/bin/env bash
# Generated by orca-setup from .orca-setup.json; change that file or the kit, not this one.
# Starts and finishes a reviewer in one call each, instead of four and three separate architect
# turns that each re-read the architect's whole context.
# Usage:
#   ./scripts/orca/review.sh start <NNN-slug> T<n> <k>
#       opens a fresh reviewer terminal in the plan worktree, waits until it is idle, creates the
#       review task for RUN/T<n>.review-<k>.spec.md and dispatches it. Last line:
#       REVIEW STARTED terminal=<handle> dispatch=<id>
#   ./scripts/orca/review.sh finish <NNN-slug> <terminal> <dispatch>
#       after the reviewer's worker_done: releases the dispatch, closes the terminal and prints `git status --porcelain` of the worktree. Last line: REVIEW FINISHED,
#       or `REVIEW FAILED head moved <before> -> <after>` when the branch changed during the review
#       (a test the reviewer ran committed into the worktree); the cleanup has run either way.
# Any failed step prints `REVIEW FAILED <step>` with the orca output and exits 1; nothing after it runs.
set -uo pipefail
cd "$(dirname "$0")/../.." || exit 1
action=${1:?usage: review.sh start|finish <NNN-slug> ...}
slug=${2:?missing <NNN-slug>}
wt="/Users/serhii/Developer/emdash-images/.worktrees/emdash-images/$slug"
run="/Users/serhii/Developer/emdash-images/.scratch/runs/$slug"
[ -d "$wt" ] || { echo "REVIEW FAILED no worktree $wt"; exit 1; }

# Prints the value at a dotted path of an orca --json answer, or fails with the answer.
field() {
  python3 -c '
import json, sys
try:
    data = json.loads(sys.argv[1])
except ValueError:
    sys.exit(1)
if not data.get("ok"):
    sys.exit(1)
value = data
for key in sys.argv[2].split("."):
    value = value.get(key) if isinstance(value, dict) else None
if value is None:
    sys.exit(1)
print(value)
' "$1" "$2"
}

fail() {
  echo "REVIEW FAILED $1"
  echo "$2"
  exit 1
}

case "$action" in
  start)
    if [ "$action" = start ]; then
      task=${3:?missing T<n>}
      k=${4:?missing <k>}
      spec="$run/$task.review-$k.spec.md"
      title="review $task"
      what="Review $k of $task, plan $slug. Read the full review spec at $spec and follow it exactly."
      agent="reviewer --model claude-opus-5-5 --effort medium"
    fi
    [ -f "$spec" ] || fail "no spec" "$spec"
    out=$(orca terminal create --worktree "path:$wt" --title "$title" \
      --command "claude --agent $agent --settings .claude/roles/${role:-reviewer}.json --allowedTools Grep,Glob" --json 2>&1)
    term=$(field "$out" result.terminal.handle) || fail "terminal create" "$out"
    out=$(orca terminal wait --terminal "$term" --for tui-idle --timeout-ms 300000 --json 2>&1)
    [ "$(field "$out" result.wait.satisfied)" = "True" ] || fail "terminal wait (terminal=$term)" "$out"
    out=$(orca orchestration task-create --spec "$what" --json 2>&1)
    id=$(field "$out" result.task.id) || fail "task-create (terminal=$term)" "$out"
    out=$(orca orchestration worker-start --task "$id" --terminal "$term" --worktree "path:$wt" --json 2>&1)
    dispatch=$(field "$out" result.dispatchId) || fail "worker-start (terminal=$term task=$id)" "$out"
    git -C "$wt" rev-parse HEAD >"$run/.review-$term.head" 2>/dev/null
    echo "REVIEW STARTED terminal=$term dispatch=$dispatch"
    ;;
  finish)
    term=${3:?missing <terminal>}
    dispatch=${4:?missing <dispatch>}
    # A terminal the architect created stays after release (retained, external_terminal).
    out=$(orca orchestration worker-release --dispatch "$dispatch" --json 2>&1)
    field "$out" result >/dev/null || fail "worker-release" "$out"
    out=$(orca terminal close --terminal "$term" --json 2>&1)
    # A terminal that is already gone is closed.
    field "$out" result >/dev/null || grep -q terminal_not_found <<<"$out" || fail "terminal close" "$out"
    echo "== worktree status"
    git -C "$wt" status --porcelain
    before=$(cat "$run/.review-$term.head" 2>/dev/null)
    after=$(git -C "$wt" rev-parse HEAD 2>/dev/null)
    rm -f "$run/.review-$term.head"
    if [ -n "$before" ] && [ "$before" != "$after" ]; then
      echo "REVIEW FAILED head moved $before -> $after"
      exit 1
    fi
    echo "REVIEW FINISHED"
    ;;
  *)
    echo "usage: review.sh start|finish <NNN-slug> ..."
    exit 2
    ;;
esac
